import subprocess, re
def sh(*a): return subprocess.run(a,capture_output=True,text=True).stdout
comms=set()
for b in ["rachel","monica","phoebe","joey","chandler","ross"]:
    for sha in sh("git","log","--format=%H","origin/friend/"+b).split():
        if "Friend-Message: 1" in sh("git","log","-1","--format=%B",sha): comms.add(sha)
tx=set()
for f in sh("git","ls-tree","-r","--name-only","origin/main","S01/").split():
    if f.startswith("S01/E"):
        for m in re.finditer(r"Source: friend/\w+ @ ([0-9a-f]{40})", sh("git","show","origin/main:"+f)): tx.add(m.group(1))
missing=sorted(comms-tx)
print("friend msgs:",len(comms)," transcribed:",len(tx)," pending:",len(missing))
for m in missing:
    print("  pending:", m, sh("git","log","-1","--format=%cI %s",m).strip())
# joey branch integrity
tips=sh("git","rev-parse","origin/friend/joey").strip()
