print("joey commits by author:", set(sh("git","log","--format=%an <%ae>","origin/friend/joey").split("\n")))
print("joey messages all start with 'friend: Joey':", all(sh("git","log","-1","--format=%B",s).startswith("friend: Joey") for s in sh("git","log","--format=%H","origin/friend/joey").split()))
